#!/usr/bin/env python3
"""Upstream RNS 1.6.0 rncp progress-line fields (RNS/Utilities/rncp.py).

Calls upstream rncp.size_str (:891-908), RNS.prettytime (RNS/__init__.py:239)
for the float durations rncp passes it, and the percent expression str(round(prg * 100.0, 1)) used by the progress
lines (:582, :746). Writes rncp_progress.tsv: kind, input, suffix, output.
"""
import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
WORKSPACE = os.path.abspath(os.path.join(HERE, *[".."] * 6))
RNS_DIR = os.environ.get("RATSPEAK_UPSTREAM_RETICULUM_DIR") or os.path.join(WORKSPACE, "upstream", "candidate", "Reticulum")
sys.path.insert(0, RNS_DIR)
import subprocess
import RNS
assert RNS.__version__ == "1.6.0", RNS.__version__
assert os.path.realpath(RNS.__file__).startswith(os.path.realpath(RNS_DIR) + os.sep), RNS.__file__
from RNS.Utilities.rncp import size_str

SIZES = [0, 0.4, 2.5, 999, 999.4, 999.5, 1000, 1500, 999994, 999995, 1000000, 12345678, 1e24, 2.5e27]
RATES = [0, 0.1, 62.4, 124.9, 125, 1234.5, 125000000.0]
TIMES = [0.0, 0.004, 0.005, 1, 1.5, 5.234, 59.999, 60, 61, 65.234, 3600, 3661.5, 86400, 90061.25, 172800]
PROGRESS = [0.0, 0.0004, 0.00051, 0.25, 0.3333333, 0.99949, 0.9996, 1.0]

commit = subprocess.run(["git", "-C", RNS_DIR, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip() or "unknown"
rows = [f"# generated by crates/rns-tools/tests/fixtures/rncp_progress/gen_rncp_progress.py from RNS {RNS.__version__} ({commit})"]
rows += [f"size\t{repr(v)}\tB\t{size_str(v)}" for v in SIZES]
rows += [f"size\t{repr(v)}\tb\t{size_str(v, 'b')}" for v in RATES]
rows += [f"time\t{repr(float(v))}\t-\t{RNS.prettytime(float(v))}" for v in TIMES]
rows += [f"percent\t{repr(v)}\t-\t{round(v * 100.0, 1)}" for v in PROGRESS]
with open(os.path.join(HERE, "rncp_progress.tsv"), "w") as f:
    f.write("\n".join(rows) + "\n")
